140	    other = __shfl(amax, src_lane, warpSize);
141	    if (pair_lane < 2) {
142	        amax = fmaxf(amax, other);
143	    }
144	    src_lane = pair_lane == 0 ? wave_group_base + 1 : wave_lane;
145	    other = __shfl(amax, src_lane, warpSize);
146	    if (pair_lane == 0) {
147	        amax = fmaxf(amax, other);
148	    }
149	
150	    int scale_int = pair_lane == 0 ? static_cast<int>(mxfp4_scale_byte(amax)) : 0;
151	    scale_int = __shfl(scale_int, wave_group_base, warpSize);
152	
153	    if (active) {
154	        const uint8_t scale_byte = static_cast<uint8_t>(scale_int);
155	        if (pair_lane == 0) {
156	            scale_output[group] = scale_byte;
157	        }
158	
159	        const float multiplier = pow2_int(-scale_exponent_from_byte(scale_byte));
160	        const uint16_t raw_even = static_cast<uint16_t>(raw_pair & 0xffffu);
161	        const uint16_t raw_odd = static_cast<uint16_t>(raw_pair >> 16);
162	        const uint8_t even_code = quant_one<DType>(raw_even, multiplier);
163	        const uint8_t odd_code = quant_one<DType>(raw_odd, multiplier);
164	        packed_output[group * kPackedPerGroup + pair_lane] =
165	            static_cast<uint8_t>(even_code | (odd_code << 4));
166	    }
167	}
