171	// dtype: 0 = FP16, 1 = BF16. Pointers address distinct device buffers.
172	// Enqueue on stream and return a hipError_t integer; do not synchronize.
173	extern "C" int aiter_rs_quant_mxfp4_even(
174	    const void* input,
175	    void* packed_output,
176	    void* scale_output,
177	    int64_t rows,
178	    int64_t cols,
179	    int dtype,
180	    void* stream) {
181	    if (input == nullptr || packed_output == nullptr || scale_output == nullptr ||
182	        rows <= 0 || cols <= 0 || (cols % kValuesPerGroup) != 0 ||
183	        (dtype != 0 && dtype != 1)) {
184	        return static_cast<int>(hipErrorInvalidValue);
185	    }
186	
187	    const int64_t total_groups_64 = rows * (cols / kValuesPerGroup);
188	    if (total_groups_64 <= 0 || total_groups_64 > static_cast<int64_t>(INT32_MAX)) {
189	        return static_cast<int>(hipErrorInvalidValue);
190	    }
191	
192	    const int total_groups = static_cast<int>(total_groups_64);
193	    const dim3 block(kThreadsPerBlock);
194	    const dim3 grid((total_groups + kGroupsPerBlock - 1) / kGroupsPerBlock);
195	    hipStream_t hip_stream = reinterpret_cast<hipStream_t>(stream);
196	
197	    if (dtype == 0) {
198	        hipLaunchKernelGGL(HIP_KERNEL_NAME(quant_mxfp4_even_kernel<0>), grid, block, 0, hip_stream,
199	                           reinterpret_cast<const uint32_t*>(input),
200	                           reinterpret_cast<uint8_t*>(packed_output),
201	                           reinterpret_cast<uint8_t*>(scale_output),
202	                           total_groups);
203	    } else {
204	        hipLaunchKernelGGL(HIP_KERNEL_NAME(quant_mxfp4_even_kernel<1>), grid, block, 0, hip_stream,
205	                           reinterpret_cast<const uint32_t*>(input),
206	                           reinterpret_cast<uint8_t*>(packed_output),
207	                           reinterpret_cast<uint8_t*>(scale_output),
208	                           total_groups);
209	    }
210	    return static_cast<int>(hipGetLastError());
211	}
